import re
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter, column_index_from_string

path='input.xlsx'
out='output.xlsx'
wb=load_workbook(path, data_only=False)

pat = re.compile(r'([A-Za-z_]+!)?(\$?)([A-Z]{1,3})(\$?)(\d+)')

def shift_refs(formula, dx):
    def repl(m):
        prefix = m.group(1) or ''
        abs_col = m.group(2) or ''
        col = m.group(3)
        abs_row = m.group(4) or ''
        row = m.group(5)
        new_col = get_column_letter(column_index_from_string(col) + dx)
        return prefix + abs_col + new_col + abs_row + row
    return pat.sub(repl, formula)

def neighbor_values(ws, r):
    vals = {}
    for col in range(1, ws.max_column+1):
        c = ws.cell(row=r, column=col)
        if c.value is not None:
            vals[col] = c.value
    return vals

# Fill blanks that are between existing formulas in same row. Use right shifted left formula.
changed=[]
for ws in wb.worksheets:
    for r in range(1, ws.max_row+1):
        vals = neighbor_values(ws, r)
        for col in range(4, ws.max_column+1):
            if col in vals:
                continue
            if col-1 not in vals or col+1 not in vals:
                continue
            left=vals[col-1]; right=vals[col+1]
            if isinstance(left, str) and left.startswith('=') and isinstance(right, str) and right.startswith('='):
                formula = shift_refs(right, -1)
                # For non-range patterns and running sums, this should be correct; if refs would be invalid, use left shift.
                # Ensure formula is not empty
                ws.cell(row=r, column=col).value = formula
                changed.append((ws.title, r, get_column_letter(col), formula))

wb.save(out)
print('Filled', len(changed), 'cells. Saved', out)
for sheet,r,col,f in changed[:10]: print(sheet, r, col, f)

# Print gap detection after fill (between formulas)
print('\nGaps after fill:')
for ws in wb.worksheets:
    for r in range(1, ws.max_row+1):
        vals = neighbor_values(ws, r)
        gaps=[]
        for col in range(4, ws.max_column+1):
            if col not in vals:
                if col-1 in vals and col+1 in vals and isinstance(vals[col-1], str) and vals[col-1].startswith('=') and isinstance(vals[col+1], str) and vals[col+1].startswith('='):
                    gaps.append(get_column_letter(col))
        if gaps:
            print(ws.title, 'R', r, ','.join(gaps))
